package com.comfymobile.app;

import org.json.*;
import java.io.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

public final class RemoteBatchEngineTest {
 static void check(boolean condition,String message){if(!condition)throw new AssertionError(message);}
 static final class Computer implements BatchEngine.Transport {
  JSONObject plan,state;int starts,caches,version;boolean offline,cacheFailure,loseStartResponse;final Set<String> localIds=new HashSet<>();final ArrayList<String> controls=new ArrayList<>();
  public JSONObject post(JSONObject j,String path,JSONObject body)throws Exception{if(offline)throw new IOException("offline");if(path.equals("/comfy-mobile/batches")){starts++;if(state==null){plan=body;state=new JSONObject().put("completed",0).put("outputs",new JSONArray()).put("state","running").put("desired","run").put("prompt_id","computer-1").put("current_seed","1234");}if(loseStartResponse){loseStartResponse=false;throw new IOException("handoff response lost");}return state;}if(path.endsWith("/control")){int next=body.getInt("version");if(next>version){version=next;String command=body.getString("command");controls.add(command);state.put("desired",command.equals("resume")?"run":command);state.put("state",command.equals("pause")?"paused":command.equals("cancel")?"cancelled":"running");if(!command.equals("resume"))state.put("prompt_id",JSONObject.NULL);}return state;}throw new AssertionError("Phone must not submit per-image /prompt: "+path);}
  public JSONObject get(JSONObject j,String path)throws Exception{if(offline)throw new IOException("offline");if(path.equals("/comfy-mobile/capabilities"))return new JSONObject().put("desktop_workflows",true);check(path.startsWith("/comfy-mobile/batches/"),"phone only polls computer-owned batch");return new JSONObject(state.toString());}
  public String upload(JSONObject j,JSONObject input){return input.optString("name","input.png");}
  public JSONObject cache(JSONObject j,String path,String id)throws Exception{if(cacheFailure)throw new IOException("download interrupted");check(localIds.add(id),"no duplicate image download");caches++;return new JSONObject().put("id",id).put("src","images/"+id).put("width",256).put("height",256);}
  void finishWithoutPhone(int total)throws Exception{JSONArray outputs=state.getJSONArray("outputs");for(int i=state.getInt("completed")+1;i<=total;i++)outputs.put(new JSONObject().put("prompt_id","computer-"+i).put("index",i).put("seed",String.valueOf(1000+i)).put("images",new JSONArray().put(new JSONObject().put("filename","image-"+i+".png").put("subfolder","").put("type","output"))));state.put("completed",total).put("state","done").put("prompt_id",JSONObject.NULL).put("current_seed",JSONObject.NULL);}
 }
 static void tick(BatchEngine engine)throws Exception{JSONObject job=engine.store.job("text");job.put("retryAt",0);engine.store.save(job);engine.tick("text");}
 public static void main(String[] args)throws Exception{JSONObject workflows=new JSONObject(new String(Files.readAllBytes(Paths.get("assets/workflows.json")),StandardCharsets.UTF_8));File file=Files.createTempDirectory("comfy-remote-").resolve("jobs.json").toFile();BatchStore store=new BatchStore(file);JSONObject job=BatchEngineTest.job(3,"text","text");job.put("remotePreferred",true);store.start(job);Computer pc=new Computer();BatchEngine engine=new BatchEngine(store,pc,workflows);tick(engine);check(pc.starts==1&&store.job("text").getBoolean("remoteOwned"),"entire plan handed to computer once");check(pc.plan.getJSONObject("template").getJSONObject("prompt").getJSONObject("10").getJSONObject("inputs").getInt("width")==256,"original workflow size binding preserved");pc.offline=true;tick(engine);pc.finishWithoutPhone(3);check(pc.state.getInt("completed")==3,"computer completes with zero phone ticks");store=new BatchStore(file);engine=new BatchEngine(store,pc,workflows);pc.offline=false;pc.cacheFailure=true;tick(engine);check(store.hasWork(),"result download failure never stops computer batch or loses pending downloads");pc.cacheFailure=false;tick(engine);check(store.job("text").getString("task").equals("done")&&pc.caches==3,"reopened phone receives every completed result");check(store.snapshot().getJSONArray("images").length()==3,"all outputs in gallery");check(!store.snapshot().getJSONObject("jobs").getJSONObject("text").has("remotePlan"),"internal prompt template omitted from UI snapshot");check(pc.starts==1,"resume UI does not start a second computer batch");check(store.job("text").getString("seed").equals("1003"),"seed display follows last background result");
  file=Files.createTempDirectory("comfy-controls-").resolve("jobs.json").toFile();store=new BatchStore(file);job=BatchEngineTest.job(4,"text","text");job.put("remotePreferred",true);store.start(job);pc=new Computer();engine=new BatchEngine(store,pc,workflows);tick(engine);String id=job.getJSONObject("batch").getString("id");store.control("text",id,"pause");tick(engine);check(store.job("text").getString("task").equals("paused"),"computer pause synchronized");JSONObject beforeResume=store.job("text");store.control("text",id,"resume");store.save(beforeResume);check(store.job("text").getString("task").equals("between"),"late paused snapshot cannot undo resume");tick(engine);check(store.job("text").getString("task").equals("running"),"resume version survives stale worker snapshots");store.control("text",id,"cancel");tick(engine);check(store.job("text").getString("task").equals("cancelled"),"computer whole-batch cancellation synchronized");check(pc.controls.equals(Arrays.asList("pause","resume","cancel")),"ordered commands delivered once per version");
  JSONObject stale=store.job("text");stale.getJSONObject("batch").put("controlVersion",0);store.save(stale);check(store.job("text").getJSONObject("batch").getInt("controlVersion")==3,"stale snapshot cannot roll back manual command ordering");
  file=Files.createTempDirectory("comfy-handoff-").resolve("jobs.json").toFile();store=new BatchStore(file);job=BatchEngineTest.job(3,"text","text");job.put("remotePreferred",true);store.start(job);pc=new Computer();pc.loseStartResponse=true;engine=new BatchEngine(store,pc,workflows);tick(engine);pc.finishWithoutPhone(3);store=new BatchStore(file);engine=new BatchEngine(store,pc,workflows);tick(engine);check(store.job("text").getString("task").equals("done")&&pc.caches==3&&pc.starts==2,"lost handoff response reattaches idempotently after process recreation");
  System.out.println("PASS: computer owns entire batch, phone offline/process loss cannot pause generation, all outputs recovered, interrupted downloads retry, workflow binding preserved, versioned pause/resume/cancel and private template filtering");
 }
}
